import unittest

from salesreport.records import Sale, filter_since


def sale(date: str) -> Sale:
    return Sale(date, "north", "widget", 1, 10.0)


class TestFilterSince(unittest.TestCase):
    def test_includes_sales_on_the_boundary(self):
        sales = [sale("2024-01-31"), sale("2024-02-01"), sale("2024-02-29")]
        kept = filter_since(sales, "2024-02-01")
        self.assertEqual([s.date for s in kept], ["2024-02-01", "2024-02-29"])

    def test_keeps_everything_when_all_sales_are_newer(self):
        sales = [sale("2024-06-01")]
        self.assertEqual(filter_since(sales, "2024-01-01"), sales)

    def test_empty_when_all_sales_are_older(self):
        sales = [sale("2024-01-31")]
        self.assertEqual(filter_since(sales, "2024-02-01"), [])


if __name__ == "__main__":
    unittest.main()

